import { LoaderCircle } from "lucide-react";
import {
  type CSSProperties,
  type FieldsetHTMLAttributes,
} from "react";
import {
  fieldHintClasses,
  fieldStatusMessages,
  getFieldStateColorClass,
  getFieldStatusIcon,
  roundedClasses,
  type FieldSize,
  type FieldStatus,
  type Rounded,
} from "./form";
import { Icon } from "./Icon";
import { mergeClasses } from "./classes";
import {
  BalsaThemeContext,
  useControllableState,
  useResolvedThemeProps,
} from "./theme-context";
import type { ThemeInput } from "./theme";
import type { SemanticColor } from "./types";

export interface RadioGroupOption {
  value: string;
  label: string;
  description?: string;
  disabled?: boolean;
}

export type RadioGroupLayout = "column" | "row" | "cards";

export interface RadioGroupProps
  extends Omit<FieldsetHTMLAttributes<HTMLFieldSetElement>, "onChange"> {
  id: string;
  label: string;
  options: readonly RadioGroupOption[];
  name?: string;
  layout?: RadioGroupLayout;
  color?: SemanticColor;
  size?: FieldSize;
  rounded?: Rounded;
  hint?: string;
  disabled?: boolean;
  loading?: boolean;
  status?: FieldStatus;
  statusMessage?: string;
  required?: boolean;
  theme?: ThemeInput;
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
}

const radioColorClasses: Readonly<Record<SemanticColor, {
  indicator: string;
  selectedCard: string;
  selectedDescription: string;
}>> = {
  primary: {
    indicator: "after:bg-balsa-primary-foreground peer-checked:border-balsa-primary peer-checked:bg-balsa-primary",
    selectedCard: "border-balsa-primary bg-balsa-primary text-balsa-primary-foreground hover:border-balsa-primary hover:bg-balsa-primary active:bg-balsa-primary",
    selectedDescription: "text-balsa-primary-foreground/80",
  },
  secondary: {
    indicator: "after:bg-balsa-secondary-foreground peer-checked:border-balsa-secondary peer-checked:bg-balsa-secondary",
    selectedCard: "border-balsa-secondary bg-balsa-secondary text-balsa-secondary-foreground hover:border-balsa-secondary hover:bg-balsa-secondary active:bg-balsa-secondary",
    selectedDescription: "text-balsa-secondary-foreground/80",
  },
  accent: {
    indicator: "after:bg-balsa-accent-foreground peer-checked:border-balsa-accent peer-checked:bg-balsa-accent",
    selectedCard: "border-balsa-accent bg-balsa-accent text-balsa-accent-foreground hover:border-balsa-accent hover:bg-balsa-accent active:bg-balsa-accent",
    selectedDescription: "text-balsa-accent-foreground/80",
  },
  destructive: {
    indicator: "after:bg-balsa-destructive-foreground peer-checked:border-balsa-destructive peer-checked:bg-balsa-destructive",
    selectedCard: "border-balsa-destructive bg-balsa-destructive text-balsa-destructive-foreground hover:border-balsa-destructive hover:bg-balsa-destructive active:bg-balsa-destructive",
    selectedDescription: "text-balsa-destructive-foreground/80",
  },
  success: {
    indicator: "after:bg-balsa-success-foreground peer-checked:border-balsa-success peer-checked:bg-balsa-success",
    selectedCard: "border-balsa-success bg-balsa-success text-balsa-success-foreground hover:border-balsa-success hover:bg-balsa-success active:bg-balsa-success",
    selectedDescription: "text-balsa-success-foreground/80",
  },
  warning: {
    indicator: "after:bg-balsa-warning-foreground peer-checked:border-balsa-warning peer-checked:bg-balsa-warning",
    selectedCard: "border-balsa-warning bg-balsa-warning text-balsa-warning-foreground hover:border-balsa-warning hover:bg-balsa-warning active:bg-balsa-warning",
    selectedDescription: "text-balsa-warning-foreground/80",
  },
  info: {
    indicator: "after:bg-balsa-info-foreground peer-checked:border-balsa-info peer-checked:bg-balsa-info",
    selectedCard: "border-balsa-info bg-balsa-info text-balsa-info-foreground hover:border-balsa-info hover:bg-balsa-info active:bg-balsa-info",
    selectedDescription: "text-balsa-info-foreground/80",
  },
};

export function RadioGroup(rawProps: RadioGroupProps) {
  const { props, theme } = useResolvedThemeProps("radio-group", "fields", rawProps, {
    size: "md",
    rounded: "lg",
  } as const);
  const {
    id,
    label,
    options,
    name,
    layout = "column",
    color = "primary",
    size,
    rounded,
    hint,
    disabled = false,
    loading = false,
    status = "default",
    statusMessage,
    required = false,
    theme: _themeInput,
    value,
    defaultValue = "",
    onValueChange,
    className,
    style,
    ...domProps
  } = props;
  void _themeInput;

  const [current, setValue] = useControllableState({
    value,
    defaultValue,
    onChange: onValueChange,
  });
  const isDisabled = disabled || loading;
  const hintId = hint ? `${id}-hint` : undefined;
  const statusId = status === "unvalidated" ? `${id}-status` : undefined;
  const describedBy = [hintId, statusId].filter(Boolean).join(" ") || undefined;
  const effectiveStatusMessage = status === "unvalidated"
    ? statusMessage ?? fieldStatusMessages.unvalidated
    : undefined;
  const stateIcon = loading ? LoaderCircle : getFieldStatusIcon(status);
  const optionsClasses = layout === "row"
    ? "flex flex-wrap items-start gap-x-balsa-2xl gap-y-balsa-md"
    : layout === "cards"
      ? "grid grid-cols-1 gap-balsa-md"
      : "flex flex-col gap-balsa-md";
  const choiceClasses = mergeClasses(
    "pointer-events-none mt-balsa-4xs grid shrink-0 place-items-center rounded-full bg-balsa-input transition-[border-color,background-color,box-shadow] after:size-1.5 after:rounded-full after:opacity-0 after:content-[''] peer-checked:after:opacity-100",
    size === "sm" ? "size-4" : "size-5",
    status === "unvalidated"
      ? "border-balsa-destructive peer-focus-visible:ring-balsa-destructive/30"
      : "border-balsa-input-border peer-focus-visible:border-balsa-focus-ring peer-focus-visible:ring-balsa-focus-ring/30",
    "peer-focus-visible:ring-2",
    radioColorClasses[color].indicator,
    "peer-disabled:border-balsa-border peer-disabled:bg-balsa-disabled",
  );

  return (
    <BalsaThemeContext.Provider value={theme}>
      <fieldset
        {...domProps}
        id={id}
        data-balsa="radio-group"
        data-theme={theme.explicitPresentation?.id}
        data-theme-base={theme.explicitPresentation?.base}
        data-layout={layout}
        data-color={color}
        data-size={size}
        data-rounded={rounded}
        data-status={status}
        disabled={isDisabled}
        aria-busy={loading || undefined}
        aria-describedby={describedBy}
        style={
          {
            ...theme.explicitPresentation?.style,
            ...style,
          } as CSSProperties
        }
        className={mergeClasses("min-w-0", className)}
      >
        <legend className="mb-balsa-md text-sm font-medium leading-snug text-balsa-foreground">
          <span>{label}</span>
          {required ? <span className="text-balsa-primary" aria-hidden="true">*</span> : null}
          {stateIcon ? (
            <Icon
              icon={stateIcon}
              size="md"
              className={mergeClasses(
                loading ? "animate-spin text-balsa-info" : getFieldStateColorClass(status),
              )}
            />
          ) : null}
        </legend>

        <div className={optionsClasses}>
          {options.map((option, index) => {
            const optionId = `${id}-${index}`;
            const selected = current === option.value;
            const optionDisabled = isDisabled || option.disabled;
            return (
              <label
                key={option.value}
                htmlFor={optionId}
                className={mergeClasses(
                  "group relative flex min-w-0 cursor-pointer items-start gap-balsa-md transition-[border-color,background-color,box-shadow,opacity]",
                  layout === "cards"
                    ? "border-balsa-input-border bg-balsa-input p-balsa-lg hover:border-balsa-border-strong"
                    : "gap-balsa-md",
                  layout === "cards" ? roundedClasses[rounded] : "",
                  size === "sm" ? "text-sm" : "text-base",
                  layout === "cards" && selected ? radioColorClasses[color].selectedCard : "",
                  optionDisabled
                    ? loading
                      ? "cursor-progress opacity-60"
                      : "cursor-not-allowed opacity-60"
                    : "",
                )}
              >
                <input
                  id={optionId}
                  className="peer sr-only"
                  type="radio"
                  name={name ?? id}
                  value={option.value}
                  checked={selected}
                  disabled={option.disabled}
                  required={required}
                  aria-invalid={status === "unvalidated" || undefined}
                  aria-describedby={describedBy}
                  onChange={() => setValue(option.value)}
                />
                <span
                  data-balsa="radio-group-indicator"
                  className={choiceClasses}
                  aria-hidden="true"
                />
                <span className="min-w-0">
                  <span className="block text-sm font-medium leading-snug">{option.label}</span>
                  {option.description ? (
                    <span
                      className={mergeClasses(
                        "mt-balsa-3xs block text-sm leading-relaxed",
                        layout === "cards" && selected
                          ? radioColorClasses[color].selectedDescription
                          : "text-balsa-muted-foreground",
                      )}
                    >
                      {option.description}
                    </span>
                  ) : null}
                </span>
              </label>
            );
          })}
        </div>

        {hint ? (
          <span id={hintId} className={fieldHintClasses}>{hint}</span>
        ) : null}
        {effectiveStatusMessage ? (
          <span
            id={statusId}
            role="alert"
            className="mt-balsa-xs block text-sm font-medium text-balsa-destructive"
          >
            {effectiveStatusMessage}
          </span>
        ) : null}
      </fieldset>
    </BalsaThemeContext.Provider>
  );
}

import { CircleAlert, CircleCheckBig } from "lucide-react";
import type { IconComponent } from "./Icon";

export const fieldLabelClasses =
  "mb-balsa-2xs block text-sm font-medium leading-snug text-balsa-foreground";

export const fieldHintClasses = "mt-balsa-2xs block text-sm text-balsa-muted-foreground";

export const textControlClasses =
  "w-full rounded-lg border font-balsa-body text-balsa-input-foreground outline-none transition-[border-color,box-shadow,opacity] placeholder:text-balsa-muted-foreground focus:border-balsa-focus-ring focus:ring-2 focus:ring-balsa-focus-ring/30 disabled:border-balsa-border disabled:bg-balsa-disabled disabled:text-balsa-disabled-foreground";

export const textControlPopupClasses =
  "max-h-64 overflow-auto rounded-lg p-balsa-3xs text-balsa-surface-elevated-foreground shadow-balsa-surface transition-[opacity,transform,visibility] duration-balsa-fast ease-balsa";

export const textControlOptionClasses =
  "flex min-h-8 w-full items-center justify-between rounded-md px-balsa-sm py-balsa-2xs text-left text-sm transition-colors";

/*
 * No bare `border`. Tailwind compiles it to a literal 1px, which outranks the
 * `border-width: var(--balsa-border-width)` the stylesheet sets on these
 * controls -- so a checkbox and a radio kept a 1px edge at every border
 * setting while everything around them moved. The colour utilities stay; only
 * the width comes from the token.
 */
export const choiceInputClasses =
  "shrink-0 cursor-pointer appearance-none outline-none transition-[border-color,background-color,box-shadow,opacity] focus-visible:border-balsa-focus-ring focus-visible:ring-2 focus-visible:ring-balsa-focus-ring/30 disabled:cursor-not-allowed disabled:border-balsa-border disabled:bg-balsa-disabled";

export type FieldStatus = "default" | "validated" | "unvalidated";
export type FieldSize = "sm" | "md";
export type FieldVariant = "outline" | "surface" | "soft" | "glass";
export type Rounded = "none" | "sm" | "md" | "lg" | "xl" | "2xl" | "3xl" | "full";
export type TextareaResize = "none" | "vertical" | "both";

export const roundedClasses: Readonly<Record<Rounded, string>> = {
  none: "rounded-none",
  sm: "rounded-sm",
  md: "rounded-md",
  lg: "rounded-lg",
  xl: "rounded-xl",
  "2xl": "rounded-2xl",
  "3xl": "rounded-3xl",
  full: "rounded-full",
};

/**
 * A surface that may be contained by another one.
 *
 * `auto` means "concentric with whatever contains me": the corner follows the
 * containing surface's radius minus the inset between them, so the gap between
 * the two edges stays even instead of thickening at every corner. A surface
 * standing on its own finds nothing published to nest inside and keeps the
 * ordinary surface radius.
 *
 * Kept apart from `Rounded` because that union is shared with text controls,
 * where there is nothing to be concentric with and `auto` would be a value
 * nobody could act on.
 */
export type SurfaceRounded = Rounded | "auto";

export const surfaceRoundedClasses: Readonly<Record<SurfaceRounded, string>> = {
  ...roundedClasses,
  // Deliberately no class. The radius comes from the concentric rule in
  // balsa-theme.css, keyed on data-rounded="auto"; a utility emitted here would
  // outrank it and pin the corner to one value.
  auto: "",
};

const fieldVariantClasses: Readonly<Record<FieldVariant, string>> = {
  outline: "border-balsa-input-border bg-balsa-background",
  surface: "border-balsa-input-border bg-balsa-input",
  soft: "border-transparent bg-balsa-muted",
  glass: "border-balsa-border/70 bg-balsa-surface/70 backdrop-balsa",
};

const fieldPopupVariantClasses: Readonly<Record<FieldVariant, string>> = {
  outline: "border-balsa-input-border bg-balsa-background",
  surface: "border-balsa-border-strong bg-balsa-surface-elevated",
  soft: "border-transparent bg-balsa-muted",
  glass: "border-balsa-border/70 bg-balsa-surface/80 backdrop-balsa",
};

export interface AnchoredPopupPosition {
  left: number;
  top: number;
  width: number;
}

const textControlSizeClasses: Record<FieldSize, string[]> = {
  sm: ["h-8", "px-balsa-md", "text-sm"],
  md: ["h-9", "px-balsa-md", "text-sm"],
};

const textareaResizeClasses: Readonly<Record<TextareaResize, string>> = {
  none: "resize-none",
  vertical: "resize-y",
  both: "resize",
};

export const fieldStatusMessages: Record<
  Extract<FieldStatus, "unvalidated">,
  string
> = {
  unvalidated: "Check this information and try again.",
};

export function getTextControlClasses(
  status: FieldStatus,
  hasAdornment: boolean,
  disabled: boolean,
  loading: boolean,
  size: FieldSize = "md",
  rounded: Rounded = "lg",
  variant: FieldVariant = "surface",
): string[] {
  const resolvedSize = textControlSizeClasses[size] ? size : "md";
  return [
    textControlClasses,
    fieldVariantClasses[variant],
    roundedClasses[rounded],
    ...textControlSizeClasses[resolvedSize],
    ...(loading
      ? ["disabled:cursor-progress"]
      : disabled
        ? ["disabled:cursor-not-allowed"]
        : ["cursor-pointer"]),
    ...(status === "validated" ? ["border-balsa-success", "focus:border-balsa-success"] : []),
    ...(status === "unvalidated"
      ? ["border-balsa-destructive", "focus:border-balsa-destructive", "focus:ring-balsa-destructive/30"]
      : []),
    ...(hasAdornment ? ["pr-10"] : []),
  ];
}

export function getTextControlPopupClasses(
  rounded: Rounded = "lg",
  variant: FieldVariant = "surface",
): string[] {
  return [textControlPopupClasses, roundedClasses[rounded], fieldPopupVariantClasses[variant]];
}

export function getTextareaControlClasses(
  status: FieldStatus,
  disabled: boolean,
  loading: boolean,
  size: FieldSize = "md",
  rounded: Rounded = "lg",
  resizable: TextareaResize = "vertical",
  hasAdornment = false,
  variant: FieldVariant = "surface",
): string[] {
  return [
    textControlClasses,
    fieldVariantClasses[variant],
    "h-auto min-h-0 py-balsa-xs leading-6",
    roundedClasses[rounded],
    textareaResizeClasses[resizable],
    size === "sm" ? "px-balsa-md text-sm leading-5" : "px-balsa-md text-sm leading-6",
    ...(loading
      ? ["disabled:cursor-progress"]
      : disabled
        ? ["disabled:cursor-not-allowed"]
        : ["cursor-text"]),
    ...(status === "validated" ? ["border-balsa-success", "focus:border-balsa-success"] : []),
    ...(status === "unvalidated"
      ? ["border-balsa-destructive", "focus:border-balsa-destructive", "focus:ring-balsa-destructive/30"]
      : []),
    ...(hasAdornment ? ["pr-10"] : []),
  ];
}

export function getChoiceInputClasses(variant: FieldVariant = "surface"): string[] {
  return [choiceInputClasses, fieldVariantClasses[variant]];
}

export function getChoiceTrackClasses(variant: FieldVariant = "surface"): string {
  return fieldVariantClasses[variant];
}

export function getAnchoredPopupPosition(
  trigger: HTMLElement,
  popup: HTMLElement,
  fallbackHeight = 256,
): AnchoredPopupPosition {
  const triggerRect = trigger.getBoundingClientRect();
  const popupRect = popup.getBoundingClientRect();
  const viewportPadding = 8;
  const gap = 8;
  const width = Math.min(
    triggerRect.width,
    window.innerWidth - viewportPadding * 2,
  );
  const height = popupRect.height || fallbackHeight;
  const maxLeft = Math.max(
    viewportPadding,
    window.innerWidth - width - viewportPadding,
  );

  return {
    width,
    left: Math.min(Math.max(triggerRect.left, viewportPadding), maxLeft),
    top:
      triggerRect.bottom + gap + height <= window.innerHeight - viewportPadding
        ? triggerRect.bottom + gap
        : Math.max(viewportPadding, triggerRect.top - height - gap),
  };
}

export function getFieldStatusIcon(status: FieldStatus): IconComponent | undefined {
  if (status === "validated") return CircleCheckBig;
  if (status === "unvalidated") return CircleAlert;
  return undefined;
}

export function getFieldStateColorClass(status: FieldStatus): string {
  if (status === "unvalidated") return "text-balsa-destructive";
  if (status === "validated") return "text-balsa-success";
  return "text-balsa-muted-foreground";
}

import { extendTailwindMerge, type ClassNameValue } from "tailwind-merge";

/**
 * Every custom scale has to be declared here, not only defined in CSS.
 *
 * tailwind-merge decides which of two classes wins by knowing they belong to
 * the same group. A scale it has not been told about is not a group, so a
 * component's own `gap-balsa-md` and a caller's `gap-3` both survive the merge
 * and whichever CSS rule happens to come last decides — the caller's override
 * silently stops working. That is what happened the moment the spacing scale
 * landed, and it is invisible in the source: the class list looks right.
 */
const twMerge = extendTailwindMerge({
  extend: {
    theme: {
      radius: ["balsa-control", "balsa-surface", "balsa-panel"],
      text: [
        "balsa-2xs",
        "balsa-xs",
        "balsa-sm",
        "balsa-base",
        "balsa-prose",
        "balsa-lg",
        "balsa-xl",
        "balsa-2xl",
        "balsa-3xl",
        "balsa-4xl",
        "balsa-5xl",
        "balsa-6xl",
      ],
      leading: ["balsa-tight", "balsa-snug", "balsa-normal", "balsa-relaxed", "balsa-prose"],
      tracking: ["balsa-title", "balsa-normal", "balsa-label"],
      shadow: [
        "balsa-control",
        "balsa-surface",
        "balsa-panel",
        "balsa-sm",
        "balsa-md",
        "balsa-lg",
        "balsa-detail",
      ],
      spacing: [
        "balsa-4xs",
        "balsa-3xs",
        "balsa-2xs",
        "balsa-xs",
        "balsa-sm",
        "balsa-md",
        "balsa-lg",
        "balsa-xl",
        "balsa-2xl",
        "balsa-3xl",
        "balsa-section-sm",
        "balsa-section-md",
        "balsa-section-lg",
        "balsa-control-inline",
        "balsa-density-compact",
        "balsa-density-default",
        "balsa-density-comfortable",
      ],
    },
    classGroups: {
      // `backdrop-balsa` is a custom utility rather than a value on a scale, so
      // it has to join the group it competes with by name. Without this a
      // caller's `backdrop-blur-none` and the component's `backdrop-balsa` both
      // survive the merge and CSS order decides which blur wins — the same
      // failure the spacing scale hit the moment it landed.
      "backdrop-blur": ["backdrop-balsa", "backdrop-balsa-overlay"],
    },
  },
});

export function mergeClasses(...inputs: unknown[]): string {
  return twMerge(...(inputs as ClassNameValue[]));
}

export function withoutClassAttribute(
  attrs: Readonly<Record<string, unknown>>,
): Record<string, unknown> {
  return Object.fromEntries(
    Object.entries(attrs).filter(([name]) => name !== "class"),
  );
}

export type ActionColor = "neutral" | "primary" | "secondary" | "accent" | "destructive";
export type StatusColor = "success" | "warning" | "info";
/**
 * Status surfaces communicate state, so they exclude neutral: an action can
 * legitimately carry no emphasis, but a status that means nothing is not a status.
 */
export type SemanticColor = Exclude<ActionColor, "neutral"> | StatusColor;
export type Rounded = "none" | "sm" | "md" | "lg" | "xl" | "2xl" | "3xl" | "full";
export type CardVariant = "surface" | "elevated" | "muted" | "outline" | "soft" | "glass";
export type CardColor = ActionColor;
export type CardPadding = "none" | "sm" | "md" | "lg";
export type CardSize = Exclude<CardPadding, "none">;

interface ActionColorClassSet {
  solid: string[];
  soft: string[];
  outline: string[];
  glass: string[];
  text: string[];
}

interface SemanticColorClassSet {
  solid: string[];
  soft: string[];
  outline: string[];
  glass: string[];
}

export const actionColorClasses: Readonly<Record<ActionColor, ActionColorClassSet>> = {
  // Chrome that should not compete with the content it frames: a filled neutral
  // action uses the inverse pair, and every quieter treatment resolves to the
  // plain foreground rather than a palette accent.
  neutral: {
    solid: ["bg-balsa-inverse", "text-balsa-inverse-foreground", "hover:bg-balsa-inverse/90", "active:bg-balsa-inverse/80"],
    soft: ["bg-balsa-muted", "text-balsa-foreground", "hover:bg-balsa-muted/80", "active:bg-balsa-muted/70"],
    outline: ["border-balsa-border-strong", "text-balsa-foreground", "hover:bg-balsa-muted", "active:bg-balsa-muted/80"],
    glass: ["text-balsa-foreground"],
    text: ["text-balsa-foreground", "decoration-balsa-border-strong", "hover:text-balsa-foreground", "hover:decoration-balsa-foreground"],
  },
  primary: {
    solid: ["bg-balsa-primary", "text-balsa-primary-foreground", "hover:bg-balsa-primary-hover", "active:bg-balsa-primary-active"],
    soft: ["bg-balsa-primary/15", "text-balsa-primary", "hover:bg-balsa-primary/20", "active:bg-balsa-primary/25"],
    outline: ["border-balsa-primary", "text-balsa-primary", "hover:bg-balsa-primary/15", "active:bg-balsa-primary/25"],
    glass: ["text-balsa-primary"],
    text: ["text-balsa-primary", "decoration-balsa-primary", "hover:text-balsa-primary-hover", "hover:decoration-balsa-primary-hover"],
  },
  secondary: {
    solid: ["bg-balsa-secondary", "text-balsa-secondary-foreground", "hover:bg-balsa-secondary-hover", "active:bg-balsa-secondary-active"],
    soft: ["bg-balsa-secondary/15", "text-balsa-secondary", "hover:bg-balsa-secondary/20", "active:bg-balsa-secondary/25"],
    outline: ["border-balsa-secondary", "text-balsa-secondary", "hover:bg-balsa-secondary/15", "active:bg-balsa-secondary/25"],
    glass: ["text-balsa-secondary"],
    text: ["text-balsa-secondary", "decoration-balsa-secondary", "hover:text-balsa-secondary-hover", "hover:decoration-balsa-secondary-hover"],
  },
  accent: {
    solid: ["bg-balsa-accent", "text-balsa-accent-foreground", "hover:bg-balsa-accent-hover", "active:bg-balsa-accent-active"],
    soft: ["bg-balsa-accent/15", "text-balsa-accent", "hover:bg-balsa-accent/20", "active:bg-balsa-accent/25"],
    outline: ["border-balsa-accent", "text-balsa-accent", "hover:bg-balsa-accent/15", "active:bg-balsa-accent/25"],
    glass: ["text-balsa-accent"],
    text: ["text-balsa-accent", "decoration-balsa-accent", "hover:text-balsa-accent-hover", "hover:decoration-balsa-accent-hover"],
  },
  destructive: {
